'use strict';
(() => {
 const $ = (s, root=document) => root.querySelector(s);
 const $$ = (s, root=document) => [...root.querySelectorAll(s)];
 const products = window.PRODUCTS || [];
 const money = n => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
 const read = (key,fallback) => {try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
 const save = (key,value) => {try{localStorage.setItem(key,JSON.stringify(value))}catch{}};
 let bag=read('crease-bag',[]).filter(x=>products.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0).map(x=>({...x,qty:Math.min(x.qty,99)}));
 let favorites=read('crease-favorites',[]).filter(x=>products.some(p=>p.id===x));
 let toastTimer;
 const notify = msg => {$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)};
 function bagCount(){const n=bag.reduce((s,x)=>s+x.qty,0);$('#bag-count').textContent=n;$('#bag-open').setAttribute('aria-label',`Open shopping bag, ${n} items`);$('#dialog-count').textContent=`(${n})`}
 function add(id){const existing=bag.find(x=>x.id===id);if(existing){if(existing.qty>=99){notify('Maximum quantity is 99 per item.');return}existing.qty++}else bag.push({id,qty:1});save('crease-bag',bag);bagCount();notify('Added to your kit bag.');if($('#bag-dialog').open)renderBag()}
 function renderBag(){bagCount();if(!bag.length){$('#bag-items').innerHTML='<div class="bag-empty"><h3>YOUR NEXT GAME STARTS HERE.</h3><p>Your kit bag is empty. Find something worth playing for.</p><a class="btn" href="products.html">Explore gear →</a></div>';$('#bag-summary').innerHTML='';return}$('#bag-items').innerHTML=bag.map(x=>{const p=products.find(p=>p.id===x.id);return `<article class="bag-item"><img class="${p.imageFit==='contain'?'studio-photo':''}" src="assets/${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><p>${money(p.price)}</p><div class="quantity-control"><button data-qty="${x.id}" data-change="-1" aria-label="Decrease ${p.name} quantity">−</button><span aria-label="Quantity">${x.qty}</span><button data-qty="${x.id}" data-change="1" aria-label="Increase ${p.name} quantity">+</button></div></div><button class="remove-item" data-remove="${x.id}" aria-label="Remove ${p.name}">Remove</button></article>`}).join('');$('#bag-summary').innerHTML=`<div class="bag-total"><span>Subtotal</span><span>${money(bag.reduce((s,x)=>s+products.find(p=>p.id===x.id).price*x.qty,0))}</span></div><p class="bag-summary-note">Demo bag · sample prices. No checkout or payment is processed.</p><button class="btn" id="download-bag">Download kit list ↓</button>`}
 function favoriteStates(){$$('[data-favorite]').forEach(b=>{const p=products.find(p=>p.id===Number(b.dataset.favorite));const active=favorites.includes(p.id);b.setAttribute('aria-pressed',active);b.setAttribute('aria-label',`${active?'Unsave':'Save'} ${p.name}`)})}
 const heart='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 21-8-8C-3 6 7-1 12 6c5-7 15 0 8 7l-8 8Z"/></svg>';
 function productCard(p){return `<article class="product-card"><div class="product-image ${p.sport}${p.imageFit==='contain'?' studio':''}"><span class="product-tag">${p.tag}</span><button class="favorite icon-btn" data-favorite="${p.id}" aria-label="Save ${p.name}" aria-pressed="false">${heart}</button><button class="product-view" data-view="${p.id}" aria-label="View ${p.name}"><img class="${p.imageFit==='contain'?'studio-photo':''}" src="assets/${p.image}" alt="Photograph of ${p.name}" loading="lazy"></button><button class="quick-view" data-view="${p.id}">QUICK VIEW +</button></div><div class="product-meta"><span>${p.sport.toUpperCase()} / EQUIPMENT</span><h3><button data-view="${p.id}">${p.name}</button></h3><div class="product-bottom"><span class="price">${money(p.price)}</span><button class="add-btn" data-add="${p.id}" aria-label="Add ${p.name} to bag">+</button></div></div></article>`}
 let activeSport='all',onlySaved=false;
 const grid=$('#catalog-grid');
 if(grid){const params=new URLSearchParams(location.search);const requested=params.get('sport');if(['cricket','football','badminton','fitness'].includes(requested))activeSport=requested;const requestedBrand=params.get('brand');if(requestedBrand&&products.some(p=>p.brand===requestedBrand))$('#product-search').value=requestedBrand}
 function filterProducts(){if(!grid)return;const term=$('#product-search').value.trim().toLowerCase();let shown=products.filter(p=>(activeSport==='all'||p.sport===activeSport)&&(!onlySaved||favorites.includes(p.id))&&`${p.name} ${p.brand} ${p.sport}`.toLowerCase().includes(term));const sort=$('#product-sort').value;if(sort==='low')shown.sort((a,b)=>a.price-b.price);if(sort==='high')shown.sort((a,b)=>b.price-a.price);if(sort==='name')shown.sort((a,b)=>a.name.localeCompare(b.name));grid.innerHTML=shown.map(productCard).join('');$('#empty-results').hidden=shown.length>0;$('#results-count').textContent=`${shown.length} ${shown.length===1?'piece':'pieces'} of ${activeSport==='all'?'game-changing':activeSport} gear`;$$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.filter===activeSport));$('#saved-filter').setAttribute('aria-pressed',onlySaved);favoriteStates()}
 function showProduct(id){const p=products.find(x=>x.id===id);if(!p)return;$('#product-details').innerHTML=`<div class="detail-image"><img class="${p.imageFit==='contain'?'studio-photo':''}" src="assets/${p.image}" alt="Photograph of ${p.name}"></div><div class="detail-copy"><span class="eyebrow">${p.brand ? p.brand + ' / ' : ''}${p.sport.toUpperCase()}</span><h2>${p.name}</h2><div class="detail-price">${money(p.price)}</div><p>${p.description}</p><p>Check final specifications and availability with the store.</p><button class="btn" data-add="${p.id}">Add to kit bag +</button><p>Need a team bundle? <a class="text-link" href="team-orders.html#team-order-enquiry">Explore team orders →</a></p></div>`;$('#product-dialog').showModal()}
 function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
 document.addEventListener('click',e=>{const addBtn=e.target.closest('[data-add]');if(addBtn){add(Number(addBtn.dataset.add));return}const view=e.target.closest('[data-view]');if(view){showProduct(Number(view.dataset.view));return}const fav=e.target.closest('[data-favorite]');if(fav){const id=Number(fav.dataset.favorite);favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save('crease-favorites',favorites);favoriteStates();if(onlySaved)filterProducts();return}const filter=e.target.closest('[data-filter]');if(filter){activeSport=filter.dataset.filter;const u=new URL(location.href);u.searchParams.delete('brand');if(activeSport==='all')u.searchParams.delete('sport');else u.searchParams.set('sport',activeSport);history.replaceState(null,'',u);filterProducts();return}const close=e.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return}const qty=e.target.closest('[data-qty]');if(qty){const item=bag.find(x=>x.id===Number(qty.dataset.qty));item.qty=Math.min(99,item.qty+Number(qty.dataset.change));bag=bag.filter(x=>x.qty>0);save('crease-bag',bag);renderBag();return}const remove=e.target.closest('[data-remove]');if(remove){bag=bag.filter(x=>x.id!==Number(remove.dataset.remove));save('crease-bag',bag);renderBag();return}if(e.target.closest('#download-bag')){const lines=bag.map(x=>{const p=products.find(p=>p.id===x.id);return `${p.name} × ${x.qty} — ${money(p.price*x.qty)}`});download(`CREASE SPORTS — MY KIT LIST\n\n${lines.join('\n')}\n\nSubtotal: ${money(bag.reduce((s,x)=>s+products.find(p=>p.id===x.id).price*x.qty,0))}\n\nFrontend demo. This is a saved kit list, not an order. All prices are illustrative.`, 'crease-sports-kit-list.txt')}});
 $('#bag-open').addEventListener('click',()=>{renderBag();$('#bag-dialog').showModal()});
 $$('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}}));
 const menu=$('#menu-toggle');menu.addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#home-dropdown-toggle')?.getAttribute('aria-expanded')!=='true'){$('#navigation').classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')}});
 function themeLabel(){$('#theme-toggle').setAttribute('aria-label',`Switch to ${document.documentElement.dataset.theme==='dark'?'light':'dark'} theme`)}themeLabel();$('#theme-toggle').addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('crease-theme',theme)}catch{}themeLabel()});
 function directionLabel(){const rtl=document.documentElement.dir==='rtl';$('#direction-toggle').textContent=rtl?'LTR':'RTL';$('#direction-toggle').setAttribute('aria-label',`Switch to ${rtl?'left-to-right':'right-to-left'} layout`)}directionLabel();$('#direction-toggle').addEventListener('click',()=>{document.documentElement.dir=document.documentElement.dir==='rtl'?'ltr':'rtl';try{localStorage.setItem('crease-dir',document.documentElement.dir)}catch{}directionLabel()});
 if(grid){$('#product-search').addEventListener('input',()=>{const u=new URL(location.href);u.searchParams.delete('brand');history.replaceState(null,'',u);filterProducts()});$('#product-sort').addEventListener('change',filterProducts);$('#saved-filter').addEventListener('click',()=>{onlySaved=!onlySaved;filterProducts()});$('#reset-filters').addEventListener('click',()=>{activeSport='all';onlySaved=false;$('#product-search').value='';$('#product-sort').value='featured';const u=new URL(location.href);u.searchParams.delete('sport');u.searchParams.delete('brand');history.replaceState(null,'',u);filterProducts()});filterProducts()}
 const formUrls=new Map();
 ['team-enquiry','contact-enquiry'].forEach(id=>{const form=$('#'+id);if(!form)return;const date=$('input[type=date]',form);if(date){const now=new Date();date.min=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`}form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));const team=id==='team-enquiry';const title=team?'TEAM KIT BRIEF':'CONTACT MESSAGE DRAFT';const text=`CREASE SPORTS — ${title}\nCreated: ${new Date().toLocaleDateString()}\n\n${Object.entries(data).map(([k,v])=>`${k.charAt(0).toUpperCase()+k.slice(1)}: ${String(v).trim()}`).join('\n\n')}\n\nFrontend demo only. Nothing has been sent and no order has been placed.`;if(formUrls.has(id))URL.revokeObjectURL(formUrls.get(id));const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));formUrls.set(id,url);const status=$('.form-status',form);status.replaceChildren();const p=document.createElement('p');p.textContent=team?'Your team brief is ready. Download it below to keep a copy.':'Your message draft is ready. Download it below to keep a copy.';const a=document.createElement('a');a.href=url;a.download=team?'crease-team-brief.txt':'crease-contact-draft.txt';a.textContent=team?'Download team brief ↓':'Download message draft ↓';status.append(p,a);notify(team?'Team brief created. Nothing has been sent.':'Message draft created. Nothing has been sent.')})});
 $('#back-top')?.addEventListener('click',()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));$('#year').textContent='2026';bagCount();favoriteStates();
})();
